window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-498e6f374c19351f"]={"versions": [{"id": "FIG-498e6f374c19351f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodus (Transmission Mode, TM) im AUTOSAR COM Modul (Classic Platform). Dargestellt ist der Anwendungsfall 4a (Use case 4a): Umschaltung des Transmission Mode Selection (TMS) zwischen periodischem Senden (PERIODIC) und ereignisgesteuertem Mehrfachversand (DIRECT / N-Times mit n = 3) unter Berücksichtigung von Mindestsendeabständen und Ausführungszeitpunkten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse ($t$)</strong>: Kontinuierliche Zeitachse mit Achsenunterbrechung.</li>\n<li><strong>Signal- bzw. Datenwert ($v=a$, $v=b$)</strong>: Applikationsseitige Signalwerte, die den Zustand des Transmission Mode Selection (TMS) steuern ($v=a$ für periodischen Modus, $v=b$ für DIRECT/N-Times).</li>\n<li><strong>Trigger-Ereignis (Blitz-Symbol)</strong>: Schreiboperation bzw. Signalaktualisierung durch die Applikation (<code>Com_SendSignal</code> / <code>Com_SendSignalGroup</code>).</li>\n<li><strong>Sendezeitpunkte (grüne vertikale Pfeile)</strong>: Tatsächliche I-PDU-Sendeanforderungen an die unterlagerte Schicht (PDU Router).</li>\n<li><strong>Verworfener/verzögerter Sendeimpuls (blauer gestrichelter Pfeil)</strong>: Durch Mindestsendeabstand blockierter Sendeversuch.</li>\n<li><strong>Timing-Parameter</strong>:</li>\n<li>$t_c$: Zykluszeit der periodischen Übertragung (<code>ComTxModeTimePeriod</code>).</li>\n<li>$t_d$: Wiederholabstand bei N-Times-Übertragung (<code>ComTxModeRepetitionPeriod</code>).</li>\n<li>$t_{r, min}$: Minimale Verzögerungszeit / Reaktionszeit bis zur tatsächlichen Übertragung nach Triggerung.</li>\n<li>$dt$: Mindestsendeabstand (Minimum Delay Time, MDT / <code>ComMinimumDelayTime</code>).</li>\n<li>$>dt$: Zeitspanne größer als der Mindestsendeabstand über die Achsenunterbrechung hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Periodischer Modus ($v=a$)</strong>: Die I-PDU wird zyklisch mit dem festen Zeitabstand $t_c$ übertragen.</li>\n<li><strong>TMS-Umschaltung auf $v=b$</strong>: Ein Schreibzugriff der Applikation setzt $v=b$ und triggert den DIRECT/N-Times-Modus ($n=3$). Da der Mindestsendeabstand $dt$ seit der letzten periodischen Übertragung abgelaufen ist, erfolgt nach der Verzögerung $t_{r, min}$ die erste Übertragung, gefolgt von zwei Wiederholungen im festen Abstand $t_d$ (insgesamt $n=3$ Übertragungen).</li>\n<li><strong>TMS-Umschaltung zurück auf $v=a$</strong>: Nach Ablauf einer Pause $>dt$ schaltet ein erneuter Schreibzugriff auf $v=a$ um. Nach $t_{r, min}$ setzt das zyklische Senden wieder mit der Periode $t_c$ ein.</li>\n<li><strong>Kollision mit Mindestsendeabstand ($dt$)</strong>: Ein erneuter Aufruf mit $v=b$ fällt in das aktive Zeitfenster des Mindestsendeabstands $dt$ der vorherigen zyklischen Sendung. Die direkte Übertragung wird blockiert (blauer gestrichelter Pfeil) und erst nach Ablauf von $dt$ (bzw. nach $t_{r, min}$) freigegeben, gefolgt von den zwei weiteren N-Times-Wiederholungen im Abstand $t_d$.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert normativ das Zusammenwirken von TMS-Moduswechseln, Wiederholungszählern (<code>ComTxModeNumberOfRepetitions = 3</code>), Zykluszeiten (<code>ComTxModeTimePeriod</code>), Wiederholungsabständen (<code>ComTxModeRepetitionPeriod</code>) und der Minimum Delay Time (<code>ComMinimumDelayTime</code>). Entwickler müssen sicherstellen, dass bei TMS-Wechseln zu DIRECT/N-Times laufende MDT-Timer respektiert werden und Übertragungsanforderungen erst nach Ablauf von MDT ausgeführt werden, ohne dass Wiederholungszähler inkonsistent werden.</p>"}, {"id": "FIG-7f83ba8c43d06446", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodus (Transmission Mode, TM) im AUTOSAR COM Modul (Classic Platform). Dargestellt ist der Anwendungsfall 4a (Use case 4a): Umschaltung des Transmission Mode Selection (TMS) zwischen periodischem Senden (PERIODIC) und ereignisgesteuertem Mehrfachversand (DIRECT / N-Times mit n = 3) unter Berücksichtigung von Mindestsendeabständen und Ausführungszeitpunkten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse ($t$)</strong>: Horizontale Zeitachse mit Unterbrechungsmarkierung.</li>\n<li><strong>Signalwerte ($v=a$, $v=b$)</strong>: Datenwerte zur Steuerung des Transmission Mode Selection (TMS).</li>\n<li><strong>Trigger-Ereignis (rotes Dreiecks-Symbol)</strong>: Signalaktualisierung/Schreibaufruf der Applikation.</li>\n<li><strong>Sendezeitpunkte (grüne Pfeile)</strong>: I-PDU-Sendeauslösungen an den PDU Router.</li>\n<li><strong>Verzögerter Sendeimpuls (blauer gestrichelter Pfeil)</strong>: Durch Mindestsendeabstand zunächst blockierter Sendezeitpunkt.</li>\n<li><strong>Timing-Parameter</strong>:</li>\n<li>$t_c$: Zykluszeit der periodischen Übertragung (<code>ComTxModeTimePeriod</code>).</li>\n<li>$t_d$: Wiederholabstand der N-Times-Aussendungen (<code>ComTxModeRepetitionPeriod</code>).</li>\n<li>$t_r$: Verzögerungs-/Reaktionszeit zwischen Trigger-Ereignis und Sendung.</li>\n<li>$d_t$: Mindestsendeabstand (Minimum Delay Time, <code>ComMinimumDelayTime</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Periodischer Modus ($v=a$)</strong>: I-PDUs werden zyklisch im Zeitintervall $t_c$ übertragen.</li>\n<li><strong>Umschaltung auf $v=b$ (DIRECT/N-Times)</strong>: Ein Trigger-Ereignis schaltet auf DIRECT/N-Times um. Nach Ablauf des Mindestsendeabstands $d_t$ und der Reaktionszeit $t_r$ erfolgt die erste Aussendung, gefolgt von zwei Wiederholungen im Abstand $t_d$ (insgesamt $n=3$).</li>\n<li><strong>Rückkehr zu $v=a$</strong>: Ein Trigger-Ereignis schaltet wieder in den periodischen Modus um; nach Verzögerung $t_r$ startet die periodische Aussendung im Takt $t_c$.</li>\n<li><strong>Triggerung während laufendem Mindestsendeabstand ($d_t$)</strong>: Ein erneuter Wechsel auf $v=b$ fällt in das Schutzintervall $d_t$ der letzten periodischen Sendung. Die Sofortübertragung wird unterdrückt (blauer gestrichelter Pfeil) und erst nach Ablauf von $d_t$ ausgeführt, woraufhin die zwei weiteren Wiederholungen im Abstand $t_d$ folgen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert normativ das Zusammenwirken von TMS-Moduswechseln, Wiederholungszählern (<code>ComTxModeNumberOfRepetitions = 3</code>), Zykluszeiten (<code>ComTxModeTimePeriod</code>), Wiederholungsabständen (<code>ComTxModeRepetitionPeriod</code>) und der Minimum Delay Time (<code>ComMinimumDelayTime</code>). Entwickler müssen sicherstellen, dass bei TMS-Wechseln zu DIRECT/N-Times laufende MDT-Timer respektiert werden und Übertragungsanforderungen erst nach Ablauf von MDT ausgeführt werden, ohne dass Wiederholungszähler inkonsistent werden.</p>"}], "trans": [{"from": "FIG-498e6f374c19351f", "to": "FIG-7f83ba8c43d06446", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Symbol für den Schreib-/Aktualisierungsaufruf der Applikation (Übertragungsanforderung / Wertänderung) von Blitz-Piktogramm auf nach unten weisendes rotes Dreieck geändert.</li>\n<li>Parameter- und Zeitabstandsbezeichnungen vereinheitlicht: Mindestverzögerung <code>t_{r, min}</code> zu <code>t_r</code> vereinfacht; Mindestsendeabstand (Transmission Deadline / Minimum Delay) <code>dt</code> als <code>d_t</code> mit Index gesetzt.</li>\n<li>Die Beschriftung <code>&gt;dt</code> über der Unterbrechungslinie der Zeitachse entfällt.</li>\n<li>Der bei der zweiten Umschaltung auf <code>v=b</code> verworfene bzw. verzögerte Sendeversuch (blaue gestrichelte Pfeillinie) liegt innerhalb des laufenden Mindestsendeabstands <code>d_t</code>.</li>\n</ul>"}]};
